-- +goose StatementBegin
INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.105.3',
  '2026-09-30',
  'Пульт ТВ: видно, что внутри файла — кодек, битрейт и звуковые дорожки',
  E'В карточке «Инфо» под описанием появилась строка о самом файле: разрешение, кодек, битрейт видео и всего потока, длительность и размер. Ниже — все звуковые дорожки с языком, подписью раздачи и битрейтом, и сколько в файле субтитров. У сериала показывается первая серия — остальные той же раздачи устроены так же.\n\nТа же сводка короткой строкой появилась в админке: под каждым файлом при обходе папок и под плиткой фильма. Теперь видно, что за раздача скачалась и сколько в ней лишнего, ещё до отправки на приставку.\n\nА скрипт отправки научился задавать битрейт напрямую — «--bitrate 6M» вместо подбора качества, и «--preset slow», если хочется сжать плотнее.',
  E'media-agent, library.go: mediaInfo пополнился BitRate, VBitRate и списком Audio (кодек, каналы, язык, подпись, битрейт дорожки). Битрейт дорожки у mkv лежит не в потоке, а в теге BPS; общий битрейт при пустом format.bit_rate считается по размеру и длительности; битрейт видео при отсутствии — остаток от общего за вычетом дорожек (берётся, только если больше пятой части потока). Ключ кэша разбора получил probeVersion = «v2»: старые записи без новых полей перечитываются при первом показе.\n\ninfo.go: mediaSummary(path) — разбор файла (у сериала первая серия из videosUnder, плюс число серий и общий размер) отдаётся в поле media у GET /api/info.\n\nadmin.go: adminItem получил Info; заполняется у файлов в adminChildren и у плиток-файлов в adminItemFor (только видеобиблиотеки, разбор берётся из кэша).\n\nplayer.html: mediaLine() в карточке «Инфо» (6 каналов подписываются как 5.1, 8 — как 7.1) и adMedia() строкой в строках админки.\n\nsend-series.py: --bitrate («6M», «2500k») — один проход x264 с -maxrate 1,5× и -bufsize 3×; --preset (veryfast…slow) с поправкой в оценке времени; --crf теперь без значения по умолчанию, так что явный «--crf 21» тоже включает перекодирование.\n\nЗамеры на «Ордене Феникса» (h264 1080p, 14 Мбит/с, тёмная сцена): crf 21 veryfast — 2,4 Мбит/с и 4,6× реального времени; crf 19 slow — 5,1 Мбит/с и 1× реального времени; --bitrate 4M — 4,2 Мбит/с.'
);
-- +goose StatementEnd

